const pkg = $input.first().json;
const cfg = pkg.config;
return [{ json: { ...pkg, assets: {
  mode: 'placeholder',
  audio_url: cfg.placeholder_audio_url,
  scene_image_urls: pkg.concept.scenes.map(() => cfg.placeholder_image_url),
} } }];

// One item per scene. gpt-image models take no negative prompt, so the exclusions are stated in words.
const pkg = $input.first().json;
const cfg = pkg.config;
const vs = pkg.concept.visual_style;
return pkg.concept.scenes.map((s) => ({ json: {
  run_id: pkg.run_id,
  scene_index: s.index,
  key: cfg.asset_key_prefix + '/' + pkg.run_id + '/scene-' + String(s.index).padStart(2, '0') + '.jpg',
  prompt: vs.generation_prompt_prefix + ' ' + s.visual_description + ' Colour palette: ' + s.palette.join(', ') + '. Composition leaves room at the edges for a slow push-in. Do not include: ' + vs.negative_prompt,
} }));

// Runs once after every upload has finished. Rebuilds the ordered URL list from the prompt items.
const cfg = $('Pipeline Config').first().json;
const jobs = $('Build Image Prompts').all().map((i) => i.json).sort((a, b) => a.scene_index - b.scene_index);
const base = String(cfg.asset_public_base_url).replace(/\/+$/, '');
return [{ json: { scene_image_urls: jobs.map((j) => base + '/' + j.key) } }];

const pkg = $input.first().json;
const cfg = pkg.config;
const total_ms = pkg.concept.scenes.reduce((a, s) => a + s.duration_seconds, 0) * 1000;
if (total_ms > cfg.music_max_ms) throw new Error('Piece is ' + total_ms + ' ms; music_max_ms is ' + cfg.music_max_ms + '. Split into two generations or shorten the format.');
return [{ json: {
  run_id: pkg.run_id,
  key: cfg.asset_key_prefix + '/' + pkg.run_id + '/music.mp3',
  body: { prompt: pkg.concept.audio_brief.generation_prompt, music_length_ms: total_ms, force_instrumental: true, model_id: cfg.music_model_id },
} }];

const cfg = $('Pipeline Config').first().json;
const base = String(cfg.asset_public_base_url).replace(/\/+$/, '');
return [{ json: { audio_url: base + '/' + $('Build Music Request').first().json.key } }];

const merged = $input.first().json;
const pkg = $('Restore Package').first().json;
if (!Array.isArray(merged.scene_image_urls) || merged.scene_image_urls.length !== pkg.concept.scenes.length) throw new Error('Scene image count mismatch: ' + JSON.stringify(merged.scene_image_urls));
if (!merged.audio_url) throw new Error('No audio_url from the music branch');
return [{ json: { ...pkg, assets: { mode: 'generate', audio_url: merged.audio_url, scene_image_urls: merged.scene_image_urls } } }];

// Builds the Creatomate request. Two modes (Pipeline Config.creatomate_mode):
//   source   (default) - the workflow writes the whole RenderScript for this video: exact scene count, per-scene
//                        durations, slow push/pull on each still, 3 s cross-fades, a 20 s fade to black and a
//                        matching audio fade. Nothing to build in the Creatomate editor.
//   template           - classic template_id + modifications, for a template you designed by hand. Element names:
//                        Audio, Title-Card, Fade-Out, Scene-N, Scene-N-Image, Scene-N-Label.
const pkg = $input.first().json;
const cfg = pkg.config;
const d = (cfg.format_spec && cfg.format_spec.delivery) || {};
const scenes = pkg.concept.scenes;
const total = scenes.reduce((a, s) => a + s.duration_seconds, 0);
const FADE_OUT = 20;   // seconds; format_spec hard rule: last scene fades to black over its final 20 s
const XFADE = 3;       // seconds; cross-fade between scenes
const [width, height] = String(d.resolution || '1920x1080').split('x').map(Number);
const showTitle = d.title_card && d.title_card !== 'none';

function sceneElement(s, i) {
  const n = i + 1;
  const zoomIn = i % 2 === 0;   // alternate a slow push-in and a slow pull-back so consecutive scenes never move the same way
  return {
    name: 'Scene-' + n, type: 'composition', track: 1, duration: s.duration_seconds,
    animations: i === 0 ? [] : [{ type: 'fade', duration: XFADE, transition: true }],
    elements: [
      { name: 'Scene-' + n + '-Image', type: 'image', source: pkg.assets.scene_image_urls[i], fit: 'cover',
        animations: [{ type: 'pan', scope: 'element', easing: 'linear',
          start_scale: zoomIn ? '100%' : '106%', end_scale: zoomIn ? '106%' : '100%',
          start_x: '50%', end_x: zoomIn ? '51.5%' : '48.5%', start_y: '50%', end_y: '50%' }] },
      { name: 'Scene-' + n + '-Label', type: 'text', text: s.name, visible: false, y: '92%', width: '60%',
        font_family: 'Georgia', font_size: '2.4 vmin', fill_color: 'rgba(255,255,255,0.7)', x_alignment: '50%' },
    ],
  };
}

const source = {
  output_format: cfg.creatomate_output_format || 'mp4',
  width, height, frame_rate: Number(d.fps) || 25,
  elements: [
    ...scenes.map(sceneElement),
    { name: 'Fade-Out', type: 'shape', track: 2, time: Math.max(0, total - FADE_OUT), duration: FADE_OUT,
      width: '100%', height: '100%', fill_color: '#000000', path: 'M 0 0 L 100 0 L 100 100 L 0 100 L 0 0 Z',
      opacity: [{ time: 0, value: '0%' }, { time: FADE_OUT, value: '100%', easing: 'linear' }] },
    { name: 'Title-Card', type: 'text', track: 3, time: 0, duration: 8, visible: !!showTitle, text: pkg.metadata.title,
      y: '88%', width: '70%', font_family: 'Georgia', font_size: '3 vmin', fill_color: 'rgba(255,255,255,0.85)', x_alignment: '50%',
      animations: [{ type: 'fade', time: 0, duration: 1.5 }, { type: 'fade', time: 6.5, duration: 1.5, reversed: true }] },
    // Generated music is produced at the exact piece length, so no loop. Placeholder files are short demo clips, so loop them.
    { name: 'Audio', type: 'audio', track: 4, time: 0, source: pkg.assets.audio_url, duration: null, volume: '100%', audio_fade_out: FADE_OUT, loop: pkg.assets.mode === 'placeholder' },
  ],
};

// Template mode: same intent expressed as modifications against a hand-built template.
const mods = { 'Audio.source': pkg.assets.audio_url, 'Audio.audio_fade_out': FADE_OUT, 'Audio.loop': pkg.assets.mode === 'placeholder', 'Fade-Out.time': Math.max(0, total - FADE_OUT), 'Title-Card.text': pkg.metadata.title, 'Title-Card.visible': !!showTitle };
scenes.forEach((s, i) => { const n = i + 1; mods['Scene-' + n + '.duration'] = s.duration_seconds; mods['Scene-' + n + '-Image.source'] = pkg.assets.scene_image_urls[i]; mods['Scene-' + n + '-Label.text'] = s.name; });
for (let n = scenes.length + 1; n <= (cfg.format_spec.scene_count_max || 6); n++) { mods['Scene-' + n + '.visible'] = false; mods['Scene-' + n + '.duration'] = 0; }

const render_request = cfg.creatomate_mode === 'template'
  ? { template_id: cfg.creatomate_template_id, output_format: cfg.creatomate_output_format || 'mp4', modifications: mods, metadata: JSON.stringify({ run_id: pkg.run_id }) }
  : { source, metadata: JSON.stringify({ run_id: pkg.run_id }) };
return [{ json: { ...pkg, total_seconds: total, render_request } }];

function appendHistory(entry) {
  const store = $getWorkflowStaticData('global');
  store.history = Array.isArray(store.history) ? store.history : [];
  store.history.push(entry);
  if (store.history.length > 60) store.history = store.history.slice(-60);
}
const pkg = $input.first().json;
appendHistory({ date: pkg.today, run_id: pkg.run_id, status: 'stubbed', format_family: pkg.concept.format_family, theme: pkg.concept.theme, palette: pkg.concept.visual_style.global_palette, mood: pkg.concept.audio_brief.mood, title: pkg.metadata.title });
const rr = pkg.render_request;
const summary = rr.source
  ? { mode: 'source', output: rr.source.output_format + ' ' + rr.source.width + 'x' + rr.source.height + '@' + rr.source.frame_rate, total_seconds: pkg.total_seconds, scenes: rr.source.elements.filter((e) => e.type === 'composition').map((e) => ({ name: e.name, duration: e.duration, image: e.elements[0].source })), audio: rr.source.elements.find((e) => e.type === 'audio').source, fade_out_at: rr.source.elements.find((e) => e.name === 'Fade-Out').time }
  : rr;
const notice = ':white_check_mark: Concept `' + pkg.run_id + '` approved in *stub* render mode (assets: ' + pkg.assets.mode + '). Nothing was rendered or uploaded.\n\n*Render request summary:*\n```' + JSON.stringify(summary, null, 2).slice(0, 2600) + '```';
return [{ json: { run_id: pkg.run_id, notice } }];

// Creatomate returns one render object per template output; we use the first.
const r = $input.first().json;
if (!r || !r.id) throw new Error('Creatomate did not return a render id: ' + JSON.stringify(r).slice(0, 300));
const pkg = $('Build Render Request').first().json;
return [{ json: { ...pkg, render: { id: r.id, status: r.status } } }];

function appendHistory(entry) {
  const store = $getWorkflowStaticData('global');
  store.history = Array.isArray(store.history) ? store.history : [];
  store.history.push(entry);
  if (store.history.length > 60) store.history = store.history.slice(-60);
}
const up = $input.first().json;
const pkg = $('Parse Render Start').first().json;
const video_id = up.id;
if (!video_id) throw new Error('YouTube upload returned no video id: ' + JSON.stringify(up).slice(0, 300));
appendHistory({ date: pkg.today, run_id: pkg.run_id, status: 'published_private', video_id, format_family: pkg.concept.format_family, theme: pkg.concept.theme, palette: pkg.concept.visual_style.global_palette, mood: pkg.concept.audio_brief.mood, title: pkg.metadata.title });
const disclosure = pkg.metadata.ai_disclosure.required;
const notice = ':lock: Uploaded as PRIVATE for run `' + pkg.run_id + '`\n*' + pkg.metadata.title + '*\nhttps://studio.youtube.com/video/' + video_id + '/edit\nAI disclosure flag: ' + (disclosure ? 'set via API' : 'not set (' + pkg.metadata.ai_disclosure.reason + ')') + '\nReview in Studio, then set to Public by hand.';
return [{ json: { video_id, disclosure_required: disclosure, notice } }];
